function toStaffGuidance([point, action, caution]) {
    return { point, action, caution };
}

function mapMajorStaffGuidance(rows) {
    return Object.fromEntries(rows.map(([upright, reversed], index) => [index, {
        upright: toStaffGuidance(upright),
        reversed: toStaffGuidance(reversed)
    }]));
}

