function mapMinorSuitStaffGuidance(rows) {
    return Object.fromEntries(RANKS.map(([rankId], index) => [rankId, {
        upright: toStaffGuidance(rows[index][0]),
        reversed: toStaffGuidance(rows[index][1])
    }]));
}

