const THREE_CARD_SUIT_TEXT = {
    wand: 'ワンドが重なり、行動力と競争の扱いが全体を左右します。',
    cup: 'カップが重なり、感情と期待の扱いが全体を左右します。',
    sword: 'ソードが重なり、判断と言葉の鋭さが全体を左右します。',
    pentacle: 'ペンタクルが重なり、現実条件と継続性が全体を左右します。'
};

const THREE_CARD_SEMANTIC_TAGS = {
    ending: new Set(['major-13:upright', 'major-16:upright', 'sword-10:upright', 'cup-8:upright']),
    recovery: new Set(['major-15:reversed', 'major-18:reversed', 'major-20:upright', 'sword-3:reversed', 'sword-8:reversed', 'sword-9:reversed', 'sword-10:reversed', 'cup-5:reversed', 'pentacle-5:reversed']),
    clarity: new Set(['major-1:upright', 'major-11:upright', 'major-18:reversed', 'major-19:upright', 'sword-1:upright', 'sword-queen:upright', 'sword-king:upright']),
    delay: new Set(['major-10:reversed', 'major-12:upright', 'sword-2:upright', 'sword-4:upright', 'wand-3:reversed', 'wand-8:reversed']),
    support: new Set(['major-6:upright', 'cup-2:upright', 'cup-3:upright', 'cup-10:upright', 'pentacle-3:upright', 'pentacle-6:upright', 'pentacle-10:upright'])
};

const SPECIAL_ABILITY_SESSION_KEY = 'troy.specialAbilityTerminalSession.v1';
const SPECIAL_ABILITY_BOOTSTRAP_PARAM = 'abilityTerminal';

function readSpecialAbilitySession() {
    try {
        return String(sessionStorage.getItem(SPECIAL_ABILITY_SESSION_KEY) || '').trim();
    } catch (_error) {
        return '';
    }
}

function consumeSpecialAbilityBootstrap() {
    try {
        const url = new URL(window.location.href);
        const token = String(url.searchParams.get(SPECIAL_ABILITY_BOOTSTRAP_PARAM) || '').trim();
        if (token) {
            url.searchParams.delete(SPECIAL_ABILITY_BOOTSTRAP_PARAM);
            history.replaceState(history.state, '', `${url.pathname}${url.search}${url.hash}`);
        }
        return token;
    } catch (_error) {
        return '';
    }
}

const state = {
    mode: 'tarot',
    topicId: 'love',
    subtopicId: 'feelings',
    orientation: 'upright',
    deckId: 'major',
    selectedCardId: '',
    spreadMode: 'single',
    tripleSelections: [null, null, null],
    activeTripleIndex: 0,
    customersLoading: false,
    storeData: null,
    specialAbility: {
        enabled: false,
        assetsReady: false,
        totalRounds: 12,
        assetVersion: 3,
        bootstrapToken: consumeSpecialAbilityBootstrap(),
        terminalSession: readSpecialAbilitySession(),
        state: 'idle',
        token: '',
        question: null,
        questionShownAt: 0,
        ability: null,
        busy: false,
        customerRef: '',
        requestToken: 0
    }
};

const minorCards = Object.entries(SUITS).flatMap(([suitId, suit]) => RANKS.map(([rankId, rankLabel]) => ({
    id: `${suitId}-${rankId}`,
    kind: 'minor',
    deckId: suitId,
    suitId,
    suitLabel: suit.label,
    rankId,
    rankLabel,
    label: `${suit.label} ${rankLabel}`,
    keywords: MINOR_CARD_WORDS[suitId]?.[rankId] || {},
    search: `${suit.label} ${rankLabel} 小アルカナ ${suitId} ${rankId} ${Object.values(MINOR_CARD_WORDS[suitId]?.[rankId] || {}).join(' ')}`
})));

const allCards = [...MAJOR_CARDS, ...minorCards];

function $(id) {
    return document.getElementById(id);
}

function getTopic() {
    return TOPICS.find((topic) => topic.id === state.topicId) || TOPICS[0];
}

function getSubtopics(topicId = state.topicId) {
    return TOPICS.find((topic) => topic.id === topicId)?.subtopics || [];
}

function resolveSubtopic(topicId, subtopicInput) {
    const subtopics = getSubtopics(topicId);
    const subtopicId = typeof subtopicInput === 'string' ? subtopicInput : subtopicInput?.id;
    return subtopics.find((subtopic) => subtopic.id === subtopicId) || subtopics[0] || null;
}

function getSubtopic() {
    return resolveSubtopic(state.topicId, state.subtopicId);
}

function getSubtopicReadingFrame(topicId, subtopicInput) {
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    return subtopic ? SUBTOPIC_READING_FRAMES[topicId]?.[subtopic.id] || null : null;
}

function getSelectedCard() {
    return allCards.find((card) => card.id === state.selectedCardId) || null;
}

function getThreeCardSpreadFrame(topicId, subtopicInput) {
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    return subtopic ? THREE_CARD_SPREAD_FRAMES[topicId]?.[subtopic.id] || null : null;
}

function resolveTripleSelection(selection) {
    if (!selection?.cardId) return null;
    const card = allCards.find((entry) => entry.id === selection.cardId);
    if (!card) return null;
    const orientation = ORIENTATIONS[selection.orientation] ? selection.orientation : 'upright';
    return { card, orientation };
}

function getTripleSelections() {
    return state.tripleSelections.map(resolveTripleSelection);
}

function isTripleComplete(selections = getTripleSelections()) {
    return selections.length === 3 && selections.every(Boolean);
}

function isReadingSelectionComplete() {
    return state.spreadMode === 'triple' ? isTripleComplete() : !!getSelectedCard();
}

function formatReadingBody(text) {
    const value = String(text || '').trim();
    if (!value) return value;
    const lines = value.split(/\n+/)
        .flatMap((section) => section
            .match(/[^。！？!?]+[。！？!?]?/g)
            ?.map((line) => line.trim())
            .filter(Boolean) || [section.trim()])
        .filter(Boolean);
    return lines.join('\n');
}

function getSpecialReadingBody(topicId, card, orientationId) {
    if (topicId === 'love') {
        if (card?.kind === 'major') {
            return LOVE_MAJOR_READINGS[card.number]?.[orientationId] || '';
        }
        if (card?.kind === 'minor') {
            return LOVE_MINOR_READINGS[card.suitId]?.[card.rankId]?.[orientationId] || '';
        }
    }
    if (topicId === 'work') {
        if (card?.kind === 'major') {
            return WORK_MAJOR_READINGS[card.number]?.[orientationId] || '';
        }
        if (card?.kind === 'minor') {
            return WORK_MINOR_READINGS[card.suitId]?.[card.rankId]?.[orientationId] || '';
        }
    }
    if (topicId === 'relation') {
        if (card?.kind === 'major') {
            return RELATION_MAJOR_READINGS[card.number]?.[orientationId] || '';
        }
        if (card?.kind === 'minor') {
            return RELATION_MINOR_READINGS[card.suitId]?.[card.rankId]?.[orientationId] || '';
        }
    }
    if (topicId === 'future') {
        if (card?.kind === 'major') {
            return FUTURE_MAJOR_READINGS[card.number]?.[orientationId] || '';
        }
        if (card?.kind === 'minor') {
            return FUTURE_MINOR_READINGS[card.suitId]?.[card.rankId]?.[orientationId] || '';
        }
    }
    return '';
}

function normalizeWeatherLevel(level) {
    const value = Number(level);
    if (!Number.isFinite(value)) return 5;
    return Math.max(1, Math.min(10, Math.round(value)));
}

function getWeatherLevel(card, orientationId) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    if (!card) return 5;
    if (card.kind === 'major') {
        return normalizeWeatherLevel(MAJOR_WEATHER_LEVELS[card.number]?.[direction]);
    }
    return normalizeWeatherLevel(MINOR_WEATHER_LEVELS[card.suitId]?.[card.rankId]?.[direction]);
}

function getWeatherStatus(card, orientationId = state.orientation) {
    if (!card) return null;
    const level = getWeatherLevel(card, orientationId);
    const status = WEATHER_STATUSES[level] || WEATHER_STATUSES[5];
    return {
        level,
        windLabel: status.windLabel
    };
}

function getReadingWeatherStatus(topicId, subtopicInput, card, orientationId = state.orientation) {
    if (!card) return null;
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const overrideKey = `${card.id}:${direction}`;
    const overrideLevel = SUBTOPIC_WEATHER_OVERRIDES[topicId]?.[subtopic?.id]?.[overrideKey];
    const level = normalizeWeatherLevel(overrideLevel ?? getWeatherLevel(card, direction));
    const status = WEATHER_STATUSES[level] || WEATHER_STATUSES[5];
    return {
        level,
        windLabel: status.windLabel
    };
}

function getThreeCardWeatherStatus(topicId, subtopicInput, selectionsInput) {
    const selections = (selectionsInput || []).map((selection) => {
        if (selection?.card) return selection;
        return resolveTripleSelection(selection);
    });
    if (!isTripleComplete(selections)) return null;

    const rawLevels = selections.map(({ card, orientation }) => (
        getReadingWeatherStatus(topicId, subtopicInput, card, orientation)?.level || 5
    ));
    const positions = getThreeCardSpreadFrame(topicId, subtopicInput) || [];
    const levels = rawLevels.map((value, index) => {
        const role = positions[index]?.role;
        if ((role === 'obstacle' || role === 'cost') && value >= 7) return Math.min(value, 6);
        return value;
    });
    const weights = [0.25, 0.3, 0.45];
    let level = normalizeWeatherLevel(levels.reduce((sum, value, index) => sum + (value * weights[index]), 0));
    const criticalCount = levels.filter((value) => value <= 2).length;

    if (levels.every((value) => value >= 7)) level = Math.max(level, 8);
    if (levels[0] <= 3 && levels[2] >= 7) level = Math.max(6, Math.min(7, level + 1));
    if (levels[0] >= 8 && levels[2] <= 4) level = Math.min(level, 4);
    if (levels[2] >= 9 && levels[0] >= 5 && levels[1] >= 5) level = Math.max(level, 8);
    if (levels[2] <= 2) level = Math.min(level, 3);
    if (criticalCount >= 2) level = Math.min(level, 2);
    if (levels.every((value) => value <= 4)) level = Math.min(level, 3);

    level = normalizeWeatherLevel(level);
    return {
        level,
        windLabel: (WEATHER_STATUSES[level] || WEATHER_STATUSES[5]).windLabel,
        levels,
        rawLevels
    };
}

function getThreeCardFlow(levelsInput) {
    const levels = (levelsInput || []).map(normalizeWeatherLevel);
    if (levels.length !== 3) return null;
    const range = Math.max(...levels) - Math.min(...levels);
    let id = 'mixed';
    if (levels.every((level) => level >= 7)) id = 'favorable';
    else if (levels.every((level) => level <= 4)) id = 'difficult';
    else if (levels[2] - levels[0] >= 3) id = 'recovery';
    else if (levels[0] - levels[2] >= 3) id = 'decline';
    else if (range >= 5) id = 'volatile';
    else if (range <= 1) id = 'steady';
    return { id, ...THREE_CARD_FLOW_TEXT[id] };
}

function getThreeCardVerdict(topicId, subtopicInput, level) {
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const band = getVerdictBand(level);
    return SUBTOPIC_VERDICTS[topicId]?.[subtopic?.id]?.[band] || null;
}

function getThreeCardPattern(selections) {
    const resolved = (selections || []).filter(Boolean);
    const majorCount = resolved.filter(({ card }) => card.kind === 'major').length;
    const suitCounts = resolved.reduce((counts, { card }) => {
        if (card.kind === 'minor') counts[card.suitId] = (counts[card.suitId] || 0) + 1;
        return counts;
    }, {});
    const repeatedSuit = Object.entries(suitCounts).find(([, count]) => count >= 2)?.[0] || '';
    const tags = Object.fromEntries(Object.entries(THREE_CARD_SEMANTIC_TAGS).map(([tag, keys]) => [
        tag,
        resolved.filter(({ card, orientation }) => keys.has(`${card.id}:${orientation}`)).length
    ]));
    const details = [];
    if (majorCount === 3) details.push('三枚すべてが大アルカナです。一時的な出来事ではなく、状況の前提そのものが動く組み合わせです。');
    else if (majorCount === 2) details.push('大アルカナが二枚あり、目先の対応だけではなく大きな方針の見直しが必要です。');
    if (repeatedSuit) details.push(THREE_CARD_SUIT_TEXT[repeatedSuit]);
    if (tags.ending && tags.recovery) details.push('終わりを示す札と回復を示す札が共存しています。元に戻すより、不要なものを終わらせた後に立て直す流れです。');
    else if (tags.ending) details.push('終わりや刷新を示す札があります。維持することより、終える範囲を決める必要があります。');
    else if (tags.recovery) details.push('回復を示す札があります。傷を無視せず、再発条件を外せば立て直せます。');
    if (tags.clarity && tags.delay) details.push('答えは見え始めていますが、実行時期はまだ整っていません。判断と着手を分けてください。');
    if (tags.support >= 2) details.push('協力や結束を示す札が重なっています。一人で完結させるより、条件を明確にして力を借りる方が有利です。');
    return {
        majorCount,
        repeatedSuit,
        tags,
        staff: details.join(' ')
    };
}

function getVerdictBand(level) {
    const value = normalizeWeatherLevel(level);
    if (value <= 2) return 'critical';
    if (value <= 4) return 'warning';
    if (value <= 6) return 'mixed';
    if (value <= 8) return 'favorable';
    return 'excellent';
}

function getSubtopicVerdict(topicId, subtopicInput, card, orientationId) {
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const weather = getReadingWeatherStatus(topicId, subtopic, card, orientationId);
    const band = getVerdictBand(weather?.level);
    return SUBTOPIC_VERDICTS[topicId]?.[subtopic?.id]?.[band] || null;
}

function getSubtopicForecast(topicId, subtopicInput, card, orientationId) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const weather = getReadingWeatherStatus(topicId, subtopic, card, direction);
    const band = getVerdictBand(weather?.level);
    const baseForecast = SUBTOPIC_FORECASTS[topicId]?.[subtopic?.id]?.[band] || '';
    const keywords = makeStaffTextPlain(getCardKeywordText(card, direction, topicId));
    if (!baseForecast || !keywords) return baseForecast;
    const cardForecast = ['excellent', 'favorable'].includes(band)
        ? `特に「${keywords}」を活かせる場面が先に訪れます。`
        : ['critical', 'warning'].includes(band)
            ? `特に「${keywords}」に関わる問題が先に表面化します。`
            : `特に「${keywords}」をどう扱うかで結果が分かれます。`;
    return `${baseForecast}${cardForecast}`;
}

function buildSubtopicLineBodyFallback(topicId, subtopic, card, orientationId) {
    const weather = getReadingWeatherStatus(topicId, subtopic, card, orientationId);
    const keywords = makeStaffTextPlain(getCardKeywordText(card, orientationId, topicId));
    const frame = SUBTOPIC_LINE_BODY_FALLBACKS[topicId]?.[subtopic?.id];
    const tone = weather?.level >= 7 ? 'favorable' : weather?.level <= 4 ? 'difficult' : 'mixed';
    const template = frame?.[tone] || '';
    return template.replace(/\{keywords\}/g, keywords);
}

function shouldRewriteSubtopicLineBody(topicId, subtopic, body) {
    const flags = SUBTOPIC_LINE_BODY_REWRITE_FLAGS[topicId]?.[subtopic?.id] || [];
    return flags.some((pattern) => pattern.test(body));
}

function getSubtopicLineBody(topicId, subtopicInput, card, orientationId, fallbackBody = '') {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const overrideKey = `${card?.id}:${direction}`;
    const override = SUBTOPIC_LINE_BODY_OVERRIDES[topicId]?.[subtopic?.id]?.[overrideKey];
    if (override) return override;
    if (shouldRewriteSubtopicLineBody(topicId, subtopic, fallbackBody)) {
        return buildSubtopicLineBodyFallback(topicId, subtopic, card, direction) || fallbackBody;
    }
    return fallbackBody;
}

function getCardDisplayMeta(card, orientationId, topicId) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    if (card?.kind === 'major') {
        const words = getCardKeywordValue(card, direction, topicId) || card.keywords?.upright || `No.${String(card.number).padStart(2, '0')}`;
        return `大アルカナ / ${words}`;
    }
    if (card?.kind === 'minor') {
        const words = getCardKeywordValue(card, direction, topicId) || card.keywords?.upright || card.suitLabel;
        return `小アルカナ / ${words}`;
    }
    return '';
}

function getResolvedStaffFrame(topicId, subtopicInput) {
    const topicFrame = STAFF_TOPIC_FRAMES[topicId];
    const subtopicFrame = getSubtopicReadingFrame(topicId, subtopicInput);
    if (!topicFrame || !subtopicFrame) return null;
    return { ...topicFrame, ...subtopicFrame };
}

function applyStaffTopicFrame(value, topicId, subtopicInput) {
    const frame = getResolvedStaffFrame(topicId, subtopicInput);
    if (!frame) return '';
    return String(value || '').replace(/\{([a-z]+)\}/g, (match, key) => frame[key] || match);
}

function makeStaffTextPlain(value) {
    return STAFF_PLAIN_REPLACEMENTS.reduce(
        (text, [pattern, replacement]) => text.replace(pattern, replacement),
        String(value || '')
    ).replace(/\s+/g, ' ').trim();
}

function adaptStaffGuidanceText(value, topicId, subtopicInput) {
    const topicText = (STAFF_GUIDANCE_TOPIC_REPLACEMENTS[topicId] || []).reduce(
        (text, [pattern, replacement]) => text.replace(pattern, replacement),
        String(value || '')
    );
    const subtopicId = typeof subtopicInput === 'string' ? subtopicInput : subtopicInput?.id;
    return (SUBTOPIC_STAFF_GUIDANCE_REPLACEMENTS[`${topicId}.${subtopicId}`] || []).reduce(
        (text, [pattern, replacement]) => text.replace(pattern, replacement),
        topicText
    );
}

function takePlainStaffSentences(value, count = 1) {
    return formatReadingBody(value)
        .split('\n')
        .map((sentence) => makeStaffTextPlain(sentence))
        .filter(Boolean)
        .slice(0, count)
        .join('');
}

function getSimpleMeaningContext(topicId, subtopicInput) {
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    return STAFF_SIMPLE_MEANING_CONTEXTS[topicId]?.[subtopic?.id] || '';
}

function getStaffGuidanceProfile(card, orientationId) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    return card?.kind === 'major'
        ? MAJOR_STAFF_GUIDANCE[card.number]?.[direction] || null
        : MINOR_STAFF_GUIDANCE[card?.suitId]?.[card?.rankId]?.[direction] || null;
}

function getStaffGuidance(topicId, card, orientationId, subtopicInput) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    const subtopic = resolveSubtopic(topicId, subtopicInput);
    const frame = getResolvedStaffFrame(topicId, subtopicInput);
    const staffContext = SUBTOPIC_STAFF_CONTEXTS[topicId]?.[subtopic?.id];
    const profile = getStaffGuidanceProfile(card, direction);
    const cardGroup = card?.kind === 'major' ? 'major' : card?.suitId;
    const subtopicFocus = frame?.focus?.[cardGroup]?.[0] || '';
    if (!profile || !frame || !staffContext || !subtopicFocus) return null;
    const focus = takePlainStaffSentences(subtopicFocus);
    const cardPoint = adaptStaffGuidanceText(
        takePlainStaffSentences(applyStaffTopicFrame(profile.point, topicId, subtopicInput), 2),
        topicId,
        subtopic
    );
    const cardRisk = adaptStaffGuidanceText(
        takePlainStaffSentences(applyStaffTopicFrame(profile.caution, topicId, subtopicInput), 2),
        topicId,
        subtopic
    );
    const reason = [
        focus,
        cardPoint
    ].filter(Boolean).join('');
    return {
        point: reason,
        reason,
        focus,
        cardPoint,
        cardRisk,
        action: `${staffContext.action}${adaptStaffGuidanceText(
            takePlainStaffSentences(applyStaffTopicFrame(profile.action, topicId, subtopicInput)),
            topicId,
            subtopic
        )}`,
        caution: `${staffContext.caution}${adaptStaffGuidanceText(
            takePlainStaffSentences(applyStaffTopicFrame(profile.caution, topicId, subtopicInput), 2),
            topicId,
            subtopic
        )}`
    };
}

function getCardKeywordValue(card, orientationId, topicId) {
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    return TOPIC_CARD_KEYWORD_OVERRIDES[topicId]?.[card?.id]?.[direction]
        || card?.keywords?.[direction]
        || '';
}

function getCardKeywordText(card, orientationId, topicId) {
    return String(getCardKeywordValue(card, orientationId, topicId))
        .split('、')
        .map((word) => word.trim())
        .filter(Boolean)
        .join('・');
}

function formatStaffSentence(value) {
    const text = String(value || '').trim();
    if (!text || /[。！？!?]$/.test(text)) return text;
    return `${text}。`;
}

function buildStaffReading(topic, card, orientationId, subtopicInput) {
    if (!topic || !card) return '';
    const direction = ORIENTATIONS[orientationId] ? orientationId : 'upright';
    const orientation = ORIENTATIONS[direction];
    const subtopic = resolveSubtopic(topic.id, subtopicInput);
    const frame = getResolvedStaffFrame(topic.id, subtopic);
    const guidance = getStaffGuidance(topic.id, card, direction, subtopic);
    const verdict = getSubtopicVerdict(topic.id, subtopic, card, direction);
    const weather = getReadingWeatherStatus(topic.id, subtopic, card, direction);
    const forecast = getSubtopicForecast(topic.id, subtopic, card, direction);
    const keywords = getCardKeywordText(card, direction, topic.id);
    const meaningContext = getSimpleMeaningContext(topic.id, subtopic);
    if (!subtopic || !frame || !guidance || !verdict || !weather || !forecast || !keywords || !meaningContext) return '';

    return [
        `【${topic.label}・${subtopic.label}鑑定】${card.label} / ${orientation.label}`,
        `結論: 現在の風向きは${weather.windLabel}です。${takePlainStaffSentences(verdict.staff, 2)}`,
        `現状と理由: ${meaningContext}「${makeStaffTextPlain(keywords)}」が強く出ています。${guidance.reason}`,
        `近未来: ${makeStaffTextPlain(forecast)}`,
        `対策: ${guidance.action}`,
        `注意点: ${guidance.caution}`
    ].join('\n\n');
}

function renderStaffReading(element, value) {
    if (!element) return;
    const sections = String(value || '').split(/\n{2,}/).map((section) => section.trim()).filter(Boolean);
    element.replaceChildren();

    sections.forEach((section, index) => {
        const paragraph = document.createElement('p');
        if (index === 0) {
            paragraph.className = 'tarot-reading-staff-heading';
            paragraph.textContent = section;
        } else {
            const separatorIndex = section.indexOf(':');
            if (separatorIndex > 0) {
                const label = document.createElement('strong');
                label.textContent = `${section.slice(0, separatorIndex)}:`;
                paragraph.append(label, document.createTextNode(` ${section.slice(separatorIndex + 1).trim()}`));
            } else {
                paragraph.textContent = section;
            }
        }
        element.appendChild(paragraph);
    });
}

function buildLineReading(card, orientationId, specialBody, topicInput, subtopicInput) {
    if (!card || !specialBody) return '';
    const topic = typeof topicInput === 'string'
        ? TOPICS.find((entry) => entry.id === topicInput)
        : topicInput || getTopic();
    const subtopic = resolveSubtopic(topic?.id, subtopicInput);
    const weather = getReadingWeatherStatus(topic?.id, subtopic, card, orientationId);
    const frame = getSubtopicReadingFrame(topic?.id, subtopic);
    const cardGroup = card.kind === 'major' ? 'major' : card.suitId;
    const lineFocus = frame?.focus?.[cardGroup]?.[1] || '';
    const verdict = getSubtopicVerdict(topic?.id, subtopic, card, orientationId);
    const lineBody = getSubtopicLineBody(topic?.id, subtopic, card, orientationId, specialBody);
    if (!weather || !topic || !subtopic || !lineFocus || !verdict || !lineBody) return '';

    return [
        `風向き: ${weather.windLabel}`,
        '',
        formatReadingBody(verdict.line),
        '',
        formatReadingBody(lineFocus),
        '',
        formatReadingBody(lineBody)
    ].join('\n');
}

function buildReadingBundle(topic, card, orientationId, subtopicInput) {
    const subtopic = resolveSubtopic(topic?.id, subtopicInput);
    const specialBody = getSpecialReadingBody(topic?.id, card, orientationId);
    return {
        staffText: buildStaffReading(topic, card, orientationId, subtopic),
        lineText: buildLineReading(card, orientationId, specialBody, topic, subtopic)
    };
}

function takeReadingSentences(value, count = 1) {
    return formatReadingBody(value)
        .split('\n')
        .map((line) => line.trim())
        .filter(Boolean)
        .slice(0, count)
        .join('');
}

function stripSentenceEnding(value) {
    return String(value || '').trim().replace(/[。！？!?]+$/g, '');
}

function getThreeCardRoleText(role, tone, keywords, position, verdict, guidance) {
    const verdictText = takePlainStaffSentences(verdict.staff, 1);
    const keywordText = `「${keywords}」`;
    const isFavorable = tone === 'favorable';
    const isDifficult = tone === 'difficult';
    switch (role) {
    case 'hidden':
        return {
            staff: `表面の態度だけでは判断できません。${keywordText}が隠れた部分に出ており、${guidance.cardPoint}`,
            clause: `${keywordText}が表に出ていない事情として動いています`,
            line: `表に出ていない腹の底には${keywordText}がいる。口先より、その後の行動を見な。`
        };
    case 'obstacle':
        if (isFavorable) {
            return {
                staff: `本来は追い風のカードですが、${position.label}では${keywordText}の行きすぎが弱点になります。${guidance.cardRisk}`,
                clause: `${keywordText}の行きすぎが流れを止めています`,
                line: `追い風の${keywordText}も、この位置じゃ行きすぎが暗礁になる。長所が裏目に出ていないか確かめな。`
            };
        }
        if (isDifficult) {
            return {
                staff: `${keywordText}が、${position.focus}としてそのまま表れています。${guidance.cardPoint}`,
                clause: `${keywordText}が流れを止めています`,
                line: `流れを止めているのは${keywordText}だ。ここを放置したまま先へ進むな。`
            };
        }
        return {
            staff: `${keywordText}の扱い方次第で、${position.focus}が障害へ変わります。${guidance.cardPoint}`,
            clause: `${keywordText}の扱い方が流れを左右しています`,
            line: `${keywordText}が障害になるかは扱い方次第だ。曖昧なまま進むな。`
        };
    case 'action':
        return {
            staff: isFavorable
                ? `${keywordText}を活かすことが突破口です。${guidance.cardPoint}`
                : isDifficult
                    ? `このカードは、${keywordText}の問題を先に整える必要があると告げています。${guidance.cardPoint}`
                    : `${keywordText}を整えて使うことが突破口です。${guidance.cardPoint}`,
            clause: isFavorable
                ? `${keywordText}を活かす行動が突破口です`
                : isDifficult
                    ? `${keywordText}を立て直すことが突破口です`
                    : `${keywordText}の扱い方を決めることが突破口です`,
            line: isFavorable
                ? `突破口は${keywordText}だ。迷わずその力を使いな。`
                : isDifficult
                    ? `${keywordText}を抱えたまま突っ込むな。先に扱える形へ整えてから進みな。`
                    : `突破口は${keywordText}の扱い方だ。使う範囲と止める線を決めな。`
        };
    case 'outcome':
        return {
            staff: `${position.label}には${keywordText}が出ています。${guidance.cardPoint}`,
            clause: `${keywordText}が次の結果として表れます`,
            line: isFavorable
                ? `${position.label}には${keywordText}が待っている。今の流れを活かした先の景色として受け取りな。`
                : isDifficult
                    ? `${position.label}には${keywordText}が待っている。今の流れを続けた時の警告として受け取りな。`
                    : `${position.label}には${keywordText}が待っている。良くも悪くも、今の舵取りで形が決まる。`
        };
    case 'resource':
        if (isFavorable) {
            return {
                staff: `${position.label}では、${keywordText}が今使える強みとして出ています。${guidance.cardPoint}`,
                clause: `${keywordText}が今使える強みです`,
                line: `${position.label}には${keywordText}という武器がある。錆びつかせず、必要な場所へ回しな。`
            };
        }
        if (isDifficult) {
            return {
                staff: `${position.label}では、本来支えになる部分に${keywordText}の問題があります。${guidance.cardPoint}`,
                clause: `${keywordText}の立て直しが必要です`,
                line: `${position.label}を弱くしている穴は${keywordText}だ。新しい荷を積む前に、そこを補強しな。`
            };
        }
        return {
            staff: `${position.label}では、${keywordText}は強みになりますが、まだ安定して使える状態ではありません。${guidance.cardPoint}`,
            clause: `${keywordText}は使えるものの、安定させる必要があります`,
            line: `${position.label}には${keywordText}がある。だがまだ安定しちゃいない。必要な場所へ絞って使いな。`
        };
    case 'cost':
        return {
            staff: isFavorable
                ? `良いカードですが、手放す位置では${keywordText}の行きすぎを捨てる必要があります。${guidance.cardRisk}`
                : `${keywordText}に関わる執着や負担を手放す必要があります。${guidance.cardPoint}`,
            clause: `${keywordText}に関わる執着や負担を手放す必要があります`,
            line: `転機の通行料は${keywordText}に関わる執着だ。次の海へ持ち込む荷を選びな。`
        };
    case 'decision':
        return {
            staff: isDifficult
                ? `${keywordText}だけを判断基準にすると選択を誤ります。${guidance.cardPoint}`
                : `${keywordText}を判断の軸にできます。${guidance.cardPoint}`,
            clause: `${keywordText}をどう扱うかが判断の軸です`,
            line: isDifficult
                ? `${keywordText}だけで決めるな。何を守る選択なのか、条件を立て直しな。`
                : `判断の軸は${keywordText}だ。気分じゃなく、守る条件へ照らして決めな。`
        };
    case 'state':
    default:
        return {
            staff: `${verdictText}${guidance.cardPoint}`,
            clause: `${keywordText}が今の土台を示しています`,
            line: `今の海を支配しているのは${keywordText}だ。見えている現実から目を逸らすな。`
        };
    }
}

function getThreeCardPositionReading(topic, subtopic, selection, position, index) {
    const { card, orientation } = selection;
    const verdict = getSubtopicVerdict(topic.id, subtopic, card, orientation);
    const guidance = getStaffGuidance(topic.id, card, orientation, subtopic);
    const forecast = getSubtopicForecast(topic.id, subtopic, card, orientation);
    const weather = getReadingWeatherStatus(topic.id, subtopic, card, orientation);
    const keywords = makeStaffTextPlain(getCardKeywordText(card, orientation, topic.id));
    if (!verdict || !guidance || !forecast || !weather || !keywords) return null;
    const tone = weather.level >= 7 ? 'favorable' : weather.level <= 4 ? 'difficult' : 'mixed';
    const role = position.role || (index === 0 ? 'state' : index === 1 ? 'obstacle' : 'action');
    const plainPosition = {
        ...position,
        label: position.label,
        focus: makeStaffTextPlain(position.focus)
    };
    const roleText = getThreeCardRoleText(role, tone, keywords, plainPosition, verdict, guidance);
    return {
        card,
        orientation,
        position: plainPosition,
        role,
        tone,
        keywords,
        forecast,
        action: guidance.action,
        warning: guidance.caution,
        ...roleText
    };
}

function buildThreeCardConnection(positionReadings, pattern) {
    const [first, second, third] = positionReadings;
    const secondLead = second.role === 'hidden' ? 'その裏では' : second.role === 'decision' ? '次に' : 'ただし';
    const thirdLead = third.role === 'outcome' ? 'この二つが重なった先では' : 'だから';
    const patternText = takePlainStaffSentences(pattern.staff, 2);
    return [
        `三枚をつなぐと、${stripSentenceEnding(first.clause)}。`,
        `${secondLead}、${stripSentenceEnding(second.clause)}。`,
        `${thirdLead}、${stripSentenceEnding(third.clause)}。`,
        patternText
    ].filter(Boolean).join('');
}

function getThreeCardBaseForecast(topicId, subtopic, level) {
    const band = getVerdictBand(level);
    return SUBTOPIC_FORECASTS[topicId]?.[subtopic?.id]?.[band] || '';
}

function buildThreeCardNearFuture(topic, subtopic, positionReadings, weather) {
    const third = positionReadings[2];
    const baseForecast = makeStaffTextPlain(getThreeCardBaseForecast(topic.id, subtopic, weather.level));
    if (!third || !baseForecast) return '';
    const keywords = `「${third.keywords}」`;

    if (third.role === 'outcome') {
        const resultDetail = third.tone === 'favorable'
            ? `その結果は${keywords}として表れやすくなります。`
            : third.tone === 'difficult'
                ? `特に${keywords}が問題として表面化しやすくなります。`
                : `その結果は${keywords}をどう扱うかで分かれます。`;
        return `${baseForecast}${resultDetail}`;
    }

    if (third.role === 'action') {
        const condition = third.tone === 'favorable'
            ? `${keywords}の強みを活かすことが、次の変化の足がかりになります。`
            : third.tone === 'difficult'
                ? `${keywords}の問題を先に整えることが、悪化を止める条件です。`
                : `${keywords}の扱い方を決めることが、次の変化の条件です。`;
        return `${condition}${baseForecast}`;
    }

    return `${baseForecast}${third.forecast}`;
}

function getThreeCardLineRiskPhrase(reading) {
    const keywords = `「${reading.keywords}」`;
    if (reading.role === 'obstacle' && reading.tone === 'favorable') return `${keywords}の行きすぎ`;
    if (reading.role === 'action' && reading.tone === 'difficult') return `${keywords}の問題`;
    return keywords;
}

function getThreeCardLineActionDirective(reading) {
    const keywords = `「${reading.keywords}」`;
    if (reading.tone === 'favorable') return `${keywords}を活かしな`;
    if (reading.tone === 'difficult') return `${keywords}の問題を整えな`;
    return `${keywords}の扱い方を決めな`;
}

function buildThreeCardLineClosing(positionReadings, fallback) {
    const [, second, third] = positionReadings;
    const secondRisk = getThreeCardLineRiskPhrase(second);
    const thirdDirective = getThreeCardLineActionDirective(third);
    const thirdKeywords = `「${third.keywords}」`;

    if (second.role === 'obstacle' && third.role === 'action') {
        return `${secondRisk}を外し、${thirdDirective}。そこまでやって初めて、風向きが変わる。`;
    }
    if (second.role === 'hidden' && third.role === 'action') {
        return `表の顔だけで決めるな。${secondRisk}を見抜き、${thirdDirective}。`;
    }
    if (second.role === 'cost' && third.role === 'outcome') {
        if (third.tone === 'favorable') {
            return `${secondRisk}への執着を次の海へ持ち込むな。手放せば、${thirdKeywords}が次の足場になる。`;
        }
        if (third.tone === 'difficult') {
            return `${secondRisk}への執着を次の海へ持ち込むな。さもなきゃ、${thirdKeywords}がそのまま現実になる。`;
        }
        return `${secondRisk}への執着をどう手放すかで、${thirdKeywords}の形が決まる。`;
    }
    if (second.role === 'obstacle' && third.role === 'outcome') {
        if (third.tone === 'favorable') {
            return `${secondRisk}を片づければ、${thirdKeywords}が次の景色になる。暗礁を先に外しな。`;
        }
        if (third.tone === 'difficult') {
            return `${secondRisk}を放置すれば、先で${thirdKeywords}が待っている。嫌なら今ここで舵を切りな。`;
        }
        return `${secondRisk}をどう扱うかで、${thirdKeywords}の形が決まる。曖昧なまま進むな。`;
    }
    if (second.role === 'decision' && third.role === 'outcome') {
        if (second.tone === 'difficult') {
            return `${secondRisk}だけで決めるな。守る条件を立て直せば、船は${thirdKeywords}へ向かう。`;
        }
        return `${secondRisk}を判断の軸にしな。その選び方が、船を${thirdKeywords}へ運ぶ。`;
    }
    return fallback;
}

function buildThreeCardStaffReading(topic, selectionsInput, subtopicInput) {
    if (!topic) return '';
    const subtopic = resolveSubtopic(topic.id, subtopicInput);
    const positions = getThreeCardSpreadFrame(topic.id, subtopic);
    const selections = (selectionsInput || []).map((selection) => selection?.card ? selection : resolveTripleSelection(selection));
    if (!subtopic || !positions || !isTripleComplete(selections)) return '';
    const weather = getThreeCardWeatherStatus(topic.id, subtopic, selections);
    const flow = getThreeCardFlow(weather.levels);
    const verdict = getThreeCardVerdict(topic.id, subtopic, weather.level);
    const positionReadings = selections.map((selection, index) => (
        getThreeCardPositionReading(topic, subtopic, selection, positions[index], index)
    ));
    if (!flow || !verdict || positionReadings.some((reading) => !reading)) return '';
    const pattern = getThreeCardPattern(selections);
    const flowSentences = formatReadingBody(flow.staff).split('\n').map(makeStaffTextPlain).filter(Boolean);
    const flowConclusion = flowSentences[0] || makeStaffTextPlain(flow.staff);
    const connection = buildThreeCardConnection(positionReadings, pattern);
    const currentReason = positionReadings.map((reading, index) => (
        `${index + 1}枚目・${makeStaffTextPlain(reading.position.label)}: ${reading.card.label} / ${ORIENTATIONS[reading.orientation].label}。「${makeStaffTextPlain(reading.keywords)}」。${reading.staff}`
    )).join('\n');
    const nearFuture = buildThreeCardNearFuture(topic, subtopic, positionReadings, weather);
    const nextAction = positionReadings[2].action;
    const caution = positionReadings[1].warning;
    if (!nearFuture || !nextAction || !caution) return '';

    return [
        `【${topic.label}・${subtopic.label}鑑定】3枚引き`,
        `結論: 現在の風向きは${weather.windLabel}です。${takePlainStaffSentences(verdict.staff, 2)}${flowConclusion}`,
        `現状と理由:\n${currentReason}\n${connection}`,
        `近未来: ${makeStaffTextPlain(nearFuture)}`,
        `対策: ${nextAction}`,
        `注意点: ${caution}`
    ].join('\n\n');
}

function buildThreeCardLineReading(topic, selectionsInput, subtopicInput) {
    if (!topic) return '';
    const subtopic = resolveSubtopic(topic.id, subtopicInput);
    const positions = getThreeCardSpreadFrame(topic.id, subtopic);
    const selections = (selectionsInput || []).map((selection) => selection?.card ? selection : resolveTripleSelection(selection));
    if (!subtopic || !positions || !isTripleComplete(selections)) return '';
    const weather = getThreeCardWeatherStatus(topic.id, subtopic, selections);
    const flow = getThreeCardFlow(weather.levels);
    const verdict = getThreeCardVerdict(topic.id, subtopic, weather.level);
    if (!weather || !flow || !verdict) return '';

    const positionReadings = selections.map((selection, index) => (
        getThreeCardPositionReading(topic, subtopic, selection, positions[index], index)
    ));
    if (positionReadings.some((reading) => !reading)) return '';
    const cardSections = positionReadings.map((reading, index) => (
        `${index + 1}枚目「${reading.position.label}」― ${reading.keywords}。\n${reading.line}`
    ));
    const closing = buildThreeCardLineClosing(positionReadings, flow.line);

    return [
        `風向き: ${weather.windLabel}`,
        '',
        formatReadingBody(verdict.line),
        '',
        cardSections.join('\n\n'),
        '',
        closing
    ].join('\n');
}

function buildThreeCardReadingBundle(topic, selections, subtopicInput) {
    return {
        staffText: buildThreeCardStaffReading(topic, selections, subtopicInput),
        lineText: buildThreeCardLineReading(topic, selections, subtopicInput)
    };
}

function setStatus(message, tone = '') {
    const el = $('tarotReadingStatus');
    if (!el) return;
    el.textContent = message || '待機中';
    el.classList.toggle('is-error', tone === 'error');
    el.classList.toggle('is-success', tone === 'success');
}

function createButton(className, text) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = className;
    button.textContent = text;
    return button;
}

function renderTopics() {
    const list = $('tarotTopicList');
    if (!list) return;
    list.textContent = '';
    TOPICS.forEach((topic) => {
        const button = createButton('', topic.label);
        button.dataset.topicId = topic.id;
        button.setAttribute('role', 'option');
        button.setAttribute('aria-selected', topic.id === state.topicId ? 'true' : 'false');
        button.classList.toggle('is-active', topic.id === state.topicId);
        const sub = document.createElement('small');
        sub.textContent = topic.short;
        button.append(sub);
        button.addEventListener('click', () => {
            state.topicId = topic.id;
            state.subtopicId = topic.subtopics[0]?.id || '';
            renderTopics();
            renderSubtopics();
            renderSpreadSlots();
            updateResult();
        });
        list.append(button);
    });
}

function renderSubtopics() {
    const list = $('tarotSubtopicList');
    if (!list) return;
    const subtopics = getSubtopics();
    if (!subtopics.some((subtopic) => subtopic.id === state.subtopicId)) {
        state.subtopicId = subtopics[0]?.id || '';
    }
    list.textContent = '';
    subtopics.forEach((subtopic) => {
        const button = createButton('', subtopic.label);
        button.dataset.subtopicId = subtopic.id;
        button.title = subtopic.short;
        button.setAttribute('role', 'option');
        button.setAttribute('aria-selected', subtopic.id === state.subtopicId ? 'true' : 'false');
        button.classList.toggle('is-active', subtopic.id === state.subtopicId);
        button.addEventListener('click', () => {
            state.subtopicId = subtopic.id;
            renderSubtopics();
            renderSpreadSlots();
            updateResult();
        });
        list.append(button);
    });
}

function renderDeckTabs() {
    const tabs = $('tarotDeckTabs');
    if (!tabs) return;
    tabs.textContent = '';
    DECK_TABS.forEach((tab) => {
        const button = createButton('', tab.label);
        button.dataset.deckId = tab.id;
        button.classList.toggle('is-active', tab.id === state.deckId);
        button.setAttribute('aria-pressed', tab.id === state.deckId ? 'true' : 'false');
        button.addEventListener('click', () => {
            state.deckId = tab.id;
            renderDeckTabs();
            renderCardGrid();
        });
        tabs.append(button);
    });
}

function switchSpreadMode(mode) {
    if (!SPREAD_MODES[mode] || mode === state.spreadMode) return;
    if (mode === 'triple') {
        if (getSelectedCard() && !state.tripleSelections.some(Boolean)) {
            state.tripleSelections[0] = {
                cardId: state.selectedCardId,
                orientation: state.orientation
            };
        }
        const firstEmpty = state.tripleSelections.findIndex((selection) => !selection);
        state.activeTripleIndex = firstEmpty >= 0 ? firstEmpty : 0;
        const activeSelection = state.tripleSelections[state.activeTripleIndex];
        if (activeSelection?.orientation) state.orientation = activeSelection.orientation;
    } else {
        const selected = state.tripleSelections[state.activeTripleIndex]
            || state.tripleSelections.find(Boolean);
        if (selected) {
            state.selectedCardId = selected.cardId;
            state.orientation = selected.orientation;
        }
    }
    state.spreadMode = mode;
    renderSpreadMode();
    renderSpreadSlots();
    renderOrientation();
    renderCardGrid();
    updateResult();
}

function renderSpreadMode() {
    document.querySelectorAll('[data-spread-mode]').forEach((button) => {
        const mode = button.dataset.spreadMode;
        button.classList.toggle('is-active', mode === state.spreadMode);
        button.setAttribute('aria-pressed', mode === state.spreadMode ? 'true' : 'false');
        button.onclick = () => switchSpreadMode(mode);
    });
}

function renderSpreadSlots() {
    const list = $('tarotSpreadSlots');
    if (!list) return;
    const isTriple = state.spreadMode === 'triple';
    list.hidden = !isTriple;
    list.replaceChildren();
    if (!isTriple) return;
    const positions = getThreeCardSpreadFrame(state.topicId, state.subtopicId) || [];

    positions.forEach((position, index) => {
        const resolved = resolveTripleSelection(state.tripleSelections[index]);
        const wrapper = document.createElement('div');
        wrapper.className = 'tarot-reading-spread-slot';
        wrapper.classList.toggle('is-active', index === state.activeTripleIndex);
        wrapper.dataset.spreadSlot = String(index);

        const main = createButton('tarot-reading-spread-slot-main', '');
        main.setAttribute('aria-pressed', index === state.activeTripleIndex ? 'true' : 'false');
        const role = document.createElement('span');
        role.textContent = `${index + 1}枚目・${position.label}`;
        const cardName = document.createElement('strong');
        cardName.textContent = resolved?.card.label || 'カードを選択';
        const meta = document.createElement('small');
        meta.textContent = resolved
            ? `${ORIENTATIONS[resolved.orientation].label} / ${getCardKeywordText(resolved.card, resolved.orientation, state.topicId)}`
            : position.focus;
        main.append(role, cardName, meta);
        main.addEventListener('click', () => {
            state.activeTripleIndex = index;
            if (resolved) state.orientation = resolved.orientation;
            renderSpreadSlots();
            renderOrientation();
            renderCardGrid();
        });
        wrapper.append(main);

        if (resolved) {
            const remove = createButton('tarot-reading-spread-slot-remove', '×');
            remove.title = `${index + 1}枚目を外す`;
            remove.setAttribute('aria-label', `${index + 1}枚目の${resolved.card.label}を外す`);
            remove.addEventListener('click', () => {
                state.tripleSelections[index] = null;
                state.activeTripleIndex = index;
                renderSpreadSlots();
                renderCardGrid();
                updateResult();
            });
            wrapper.append(remove);
        }
        list.append(wrapper);
    });
}

function renderOrientation() {
    document.querySelectorAll('[data-orientation]').forEach((button) => {
        const orientation = button.dataset.orientation;
        button.classList.toggle('is-active', orientation === state.orientation);
        button.setAttribute('aria-pressed', orientation === state.orientation ? 'true' : 'false');
        button.onclick = () => {
            state.orientation = orientation;
            if (state.spreadMode === 'triple' && state.tripleSelections[state.activeTripleIndex]) {
                state.tripleSelections[state.activeTripleIndex] = {
                    ...state.tripleSelections[state.activeTripleIndex],
                    orientation
                };
            }
            renderOrientation();
            renderSpreadSlots();
            renderCardGrid();
            updateResult();
        };
    });
}

function getVisibleCards() {
    const search = String($('tarotCardSearch')?.value || '').trim().toLowerCase();
    if (search) {
        return allCards.filter((card) => card.search.toLowerCase().includes(search));
    }
    return allCards.filter((card) => card.deckId === state.deckId);
}

function renderCardGrid() {
    const grid = $('tarotCardGrid');
    if (!grid) return;
    grid.textContent = '';
    const cards = getVisibleCards();
    if (!cards.length) {
        const empty = document.createElement('div');
        empty.className = 'tarot-reading-card-empty';
        empty.textContent = '該当カードなし';
        grid.append(empty);
        return;
    }
    cards.forEach((card) => {
        const button = createButton('tarot-reading-card-button', '');
        const selectedTripleIndex = state.tripleSelections.findIndex((selection) => selection?.cardId === card.id);
        const isTriple = state.spreadMode === 'triple';
        const isSelected = isTriple ? selectedTripleIndex >= 0 : card.id === state.selectedCardId;
        const usedByOtherSlot = isTriple && selectedTripleIndex >= 0 && selectedTripleIndex !== state.activeTripleIndex;
        button.dataset.cardId = card.id;
        button.classList.toggle('is-major', card.kind === 'major');
        button.classList.toggle('is-selected', isSelected);
        button.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
        button.disabled = usedByOtherSlot;
        if (usedByOtherSlot) button.title = `${selectedTripleIndex + 1}枚目で選択済み`;
        const title = document.createElement('strong');
        title.textContent = card.kind === 'major' ? card.name : card.rankLabel;
        const meta = document.createElement('span');
        const cardMeta = card.kind === 'major' ? `No.${String(card.number).padStart(2, '0')}` : card.suitLabel;
        meta.textContent = selectedTripleIndex >= 0 ? `${cardMeta} / ${selectedTripleIndex + 1}枚目` : cardMeta;
        button.append(title, meta);
        button.addEventListener('click', () => {
            if (state.spreadMode === 'triple') {
                const index = state.activeTripleIndex;
                state.tripleSelections[index] = {
                    cardId: card.id,
                    orientation: state.orientation
                };
                const firstEmpty = state.tripleSelections.findIndex((selection) => !selection);
                if (firstEmpty >= 0) state.activeTripleIndex = firstEmpty;
                const activeSelection = state.tripleSelections[state.activeTripleIndex];
                if (activeSelection?.orientation) state.orientation = activeSelection.orientation;
                renderSpreadSlots();
                renderOrientation();
            } else {
                state.selectedCardId = card.id;
            }
            renderCardGrid();
            updateResult();
        });
        grid.append(button);
    });
}

function buildReading() {
    if (state.spreadMode === 'triple') {
        const selections = getTripleSelections();
        if (!isTripleComplete(selections)) {
            const selectedCount = selections.filter(Boolean).length;
            const positions = getThreeCardSpreadFrame(state.topicId, state.subtopicId) || [];
            const activePosition = positions[state.activeTripleIndex];
            return {
                staffText: `【3枚引き】${selectedCount}/3枚を選択済み\n\n${activePosition ? `${state.activeTripleIndex + 1}枚目「${activePosition.label}」のカードを選択してください。` : 'カードを3枚選択してください。'}`,
                lineText: ''
            };
        }
        return buildThreeCardReadingBundle(getTopic(), selections, getSubtopic());
    }
    const card = getSelectedCard();
    if (!card) {
        return {
            staffText: 'カードを選択してください。',
            lineText: ''
        };
    }
    return buildReadingBundle(getTopic(), card, state.orientation, getSubtopic());
}

function updateSelectedCardPreview() {
    const app = $('tarotReadingApp');
    const badge = $('tarotMajorBadge');
    const resultWrap = document.querySelector('.tarot-reading-result-wrap');
    const singlePreview = $('tarotSelectedCard');
    const triplePreview = $('tarotTriplePreview');
    const numberEl = $('tarotSelectedNumber');
    const nameEl = $('tarotSelectedName');
    const metaEl = $('tarotSelectedMeta');
    const isTriple = state.spreadMode === 'triple';
    resultWrap?.classList.toggle('is-triple', isTriple);
    if (singlePreview) singlePreview.hidden = isTriple;
    if (triplePreview) triplePreview.hidden = !isTriple;

    if (isTriple) {
        const selections = getTripleSelections();
        const positions = getThreeCardSpreadFrame(state.topicId, state.subtopicId) || [];
        const majorCount = selections.filter((selection) => selection?.card.kind === 'major').length;
        app?.classList.toggle('is-major-selected', majorCount > 0);
        if (badge) {
            badge.hidden = majorCount === 0;
            badge.textContent = majorCount ? `MAJOR ARCANA × ${majorCount}` : 'MAJOR ARCANA';
        }
        if (triplePreview) {
            triplePreview.replaceChildren();
            positions.forEach((position, index) => {
                const selection = selections[index];
                const item = document.createElement('div');
                item.className = 'tarot-reading-triple-preview-item';
                const role = document.createElement('span');
                role.textContent = `${index + 1}枚目・${position.label}`;
                const name = document.createElement('strong');
                name.textContent = selection?.card.label || '未選択';
                const meta = document.createElement('small');
                meta.textContent = selection
                    ? `${ORIENTATIONS[selection.orientation].label} / ${getCardKeywordText(selection.card, selection.orientation, state.topicId)}`
                    : 'カードを選択';
                item.append(role, name, meta);
                triplePreview.append(item);
            });
        }
        return;
    }

    const card = getSelectedCard();
    const isMajor = card?.kind === 'major';

    app?.classList.toggle('is-major-selected', !!isMajor);
    if (badge) {
        badge.hidden = !isMajor;
        badge.textContent = 'MAJOR ARCANA';
    }

    if (!card) {
        if (numberEl) numberEl.textContent = '-';
        if (nameEl) nameEl.textContent = '未選択';
        if (metaEl) metaEl.textContent = 'カードを選択';
        return;
    }

    if (numberEl) numberEl.textContent = card.kind === 'major' ? `No.${String(card.number).padStart(2, '0')}` : card.rankLabel;
    if (nameEl) nameEl.textContent = card.label;
    if (metaEl) metaEl.textContent = `${getCardDisplayMeta(card, state.orientation, state.topicId)} / ${ORIENTATIONS[state.orientation].label}`;
}

function updateWeatherStatus() {
    const el = $('tarotWeatherStatus');
    if (!el) return;
    const levelEl = $('tarotWeatherLevel');
    const titleEl = $('tarotWeatherTitle');
    const meterEl = $('tarotWeatherMeter');
    const weather = state.spreadMode === 'triple'
        ? getThreeCardWeatherStatus(state.topicId, state.subtopicId, getTripleSelections())
        : getReadingWeatherStatus(state.topicId, state.subtopicId, getSelectedCard(), state.orientation);

    el.classList.remove(...Array.from({ length: 10 }, (_, index) => `is-level-${index + 1}`));
    if (!weather) {
        el.hidden = true;
        el.style.removeProperty('--weather-level');
        return;
    }

    el.hidden = false;
    el.classList.add(`is-level-${weather.level}`);
    el.style.setProperty('--weather-level', String(weather.level));
    if (levelEl) levelEl.textContent = '風向き';
    if (titleEl) titleEl.textContent = weather.windLabel;
    if (meterEl) meterEl.style.width = `${weather.level * 10}%`;
}

function updateResult() {
    updateSelectedCardPreview();
    updateWeatherStatus();
    const staffText = $('tarotStaffReadingText');
    const lineText = $('tarotResultText');
    const generated = buildReading();
    renderStaffReading(staffText, generated.staffText);
    if (lineText) lineText.value = generated.lineText;
    updateSendButtonState();
}

function updateSendButtonState() {
    const button = $('tarotSendLine');
    if (!button || button.dataset.sending === 'true') return;
    const customerRef = String($('tarotCustomerRef')?.value || '').trim();
    button.disabled = state.mode !== 'tarot' || !isReadingSelectionComplete() || !customerRef || state.customersLoading;
}

function getResultText() {
    return String($('tarotResultText')?.value || '').trim();
}

function getPayloadCards() {
    if (state.spreadMode === 'triple') {
        const positions = getThreeCardSpreadFrame(state.topicId, state.subtopicId) || [];
        return getTripleSelections().map((selection, index) => {
            if (!selection) return null;
            return {
                position: index + 1,
                positionId: positions[index]?.id || '',
                positionLabel: positions[index]?.label || `${index + 1}枚目`,
                cardId: selection.card.id,
                cardLabel: selection.card.label,
                orientation: selection.orientation,
                orientationLabel: ORIENTATIONS[selection.orientation].label
            };
        }).filter(Boolean);
    }
    const card = getSelectedCard();
    if (!card) return [];
    return [{
        position: 1,
        positionId: 'single',
        positionLabel: '1枚引き',
        cardId: card.id,
        cardLabel: card.label,
        orientation: state.orientation,
        orientationLabel: ORIENTATIONS[state.orientation].label
    }];
}

function buildPayload() {
    const topic = getTopic();
    const subtopic = getSubtopic();
    const cards = getPayloadCards();
    const firstCard = cards[0] || {};
    return {
        requestId: `tarot-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
        customerRef: String($('tarotCustomerRef')?.value || '').trim(),
        topicId: topic.id,
        topicLabel: topic.label,
        subtopicId: subtopic?.id || '',
        subtopicLabel: subtopic?.label || '',
        spreadMode: state.spreadMode,
        spreadModeLabel: SPREAD_MODES[state.spreadMode]?.label || SPREAD_MODES.single.label,
        cards,
        cardId: firstCard.cardId || '',
        cardLabel: firstCard.cardLabel || '',
        orientation: firstCard.orientation || state.orientation,
        orientationLabel: firstCard.orientationLabel || ORIENTATIONS[state.orientation].label,
        resultText: getResultText()
    };
}

function getSelectedCustomerRef() {
    return String($('tarotCustomerRef')?.value || '').trim();
}

async function fetchSpecialAbilityJson(path, payload) {
    const headers = payload === undefined
        ? { Accept: 'application/json' }
        : { Accept: 'application/json', 'Content-Type': 'application/json' };
    if (state.specialAbility.terminalSession) {
        headers['X-Troy-Ability-Session'] = state.specialAbility.terminalSession;
    }
    if (path === '/api/special-ability/config' && state.specialAbility.bootstrapToken) {
        headers['X-Troy-Ability-Terminal'] = state.specialAbility.bootstrapToken;
    }
    const response = await fetch(path, {
        method: payload === undefined ? 'GET' : 'POST',
        headers,
        body: payload === undefined ? undefined : JSON.stringify(payload),
        cache: 'no-store'
    });
    const text = await response.text();
    let data = null;
    try {
        data = text ? JSON.parse(text) : null;
    } catch {
        data = null;
    }
    if (!response.ok || !data?.success) {
        const error = new Error(data?.error || '特殊能力判定を処理できませんでした');
        error.code = data?.code || '';
        error.status = response.status;
        throw error;
    }
    return data;
}

function getSpecialAbilityAssetUrls() {
    const totalRounds = Math.max(1, Math.min(24, Math.trunc(Number(state.specialAbility.totalRounds) || 12)));
    const assetVersion = Math.max(1, Math.trunc(Number(state.specialAbility.assetVersion) || 3));
    return Array.from({ length: totalRounds }, (_, roundIndex) => (
        ['a', 'b', 'c', 'd'].map((letter) => `/assets/special-ability/r${String(roundIndex + 1).padStart(2, '0')}-${letter}.webp?v=${assetVersion}`)
    )).flat();
}

function preloadSpecialAbilityImages() {
    return Promise.all(getSpecialAbilityAssetUrls().map((src) => new Promise((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(src);
        image.onerror = () => reject(new Error(`判定画像を読み込めませんでした: ${src}`));
        image.src = src;
    })));
}

function setSpecialAbilityIntro(message, { canStart = false } = {}) {
    const intro = $('specialAbilityIntro');
    const assessment = $('specialAbilityAssessment');
    const result = $('specialAbilityResult');
    const introText = $('specialAbilityIntroText');
    const startButton = $('specialAbilityStart');
    if (intro) intro.hidden = false;
    if (assessment) assessment.hidden = true;
    if (result) result.hidden = true;
    if (introText) introText.textContent = message;
    if (startButton) startButton.disabled = !canStart || state.specialAbility.busy;
}

function renderSpecialAbilityResult(ability) {
    const publicAbility = ability && String(ability.name || '').trim() && String(ability.effect || '').trim()
        ? { name: String(ability.name).trim(), effect: String(ability.effect).trim() }
        : null;
    if (!publicAbility) {
        setSpecialAbilityIntro('判定結果を表示できませんでした。店内リストを更新して、もう一度確認してください。');
        return;
    }
    state.specialAbility.state = 'completed';
    state.specialAbility.ability = publicAbility;
    state.specialAbility.token = '';
    state.specialAbility.question = null;
    if ($('specialAbilityIntro')) $('specialAbilityIntro').hidden = true;
    if ($('specialAbilityAssessment')) $('specialAbilityAssessment').hidden = true;
    if ($('specialAbilityResult')) $('specialAbilityResult').hidden = false;
    if ($('specialAbilityName')) $('specialAbilityName').textContent = publicAbility.name;
    if ($('specialAbilityEffect')) $('specialAbilityEffect').textContent = publicAbility.effect;
    setStatus('判定済み', 'success');
}

function setSpecialAbilityOptionsDisabled(disabled) {
    document.querySelectorAll('.special-ability-option').forEach((button) => {
        button.disabled = !!disabled;
    });
}

function renderSpecialAbilityQuestion(question) {
    if (!question || !Array.isArray(question.options) || question.options.length !== 4) {
        setSpecialAbilityIntro('判定問題を表示できませんでした。最初からやり直してください。');
        return;
    }
    state.specialAbility.state = 'in_progress';
    state.specialAbility.question = question;
    state.specialAbility.questionShownAt = performance.now();
    if ($('specialAbilityIntro')) $('specialAbilityIntro').hidden = true;
    if ($('specialAbilityResult')) $('specialAbilityResult').hidden = true;
    if ($('specialAbilityAssessment')) $('specialAbilityAssessment').hidden = false;
    if ($('specialAbilityProgressText')) $('specialAbilityProgressText').textContent = `${question.number} / ${question.total}`;
    if ($('specialAbilityProgressBar')) $('specialAbilityProgressBar').style.width = `${(question.number / question.total) * 100}%`;
    if ($('specialAbilityPrompt')) $('specialAbilityPrompt').textContent = question.prompt || '直感で一つ選んでください';
    const options = $('specialAbilityOptions');
    if (!options) return;
    options.replaceChildren();
    question.options.forEach((option) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'special-ability-option';
        button.dataset.optionId = String(option.id || '');
        button.setAttribute('aria-label', String(option.alt || '画像を選択'));
        const image = document.createElement('img');
        image.src = String(option.imageUrl || '');
        image.alt = '';
        image.decoding = 'async';
        image.draggable = false;
        button.appendChild(image);
        button.addEventListener('click', () => submitSpecialAbilityAnswer(option.id));
        options.appendChild(button);
    });
    setStatus(`特殊能力判定 ${question.number}/${question.total}`);
}

function resetSpecialAbilitySession() {
    state.specialAbility.state = 'idle';
    state.specialAbility.token = '';
    state.specialAbility.question = null;
    state.specialAbility.questionShownAt = 0;
    state.specialAbility.ability = null;
    state.specialAbility.busy = false;
}

async function checkSpecialAbilityStatus() {
    if (!state.specialAbility.enabled || state.mode !== 'ability') return;
    const customerRef = getSelectedCustomerRef();
    const requestToken = ++state.specialAbility.requestToken;
    resetSpecialAbilitySession();
    state.specialAbility.customerRef = customerRef;
    if (!customerRef) {
        setSpecialAbilityIntro('店内リストから判定するお客様を選んでください。');
        setStatus('お客様を選択');
        return;
    }
    state.specialAbility.busy = true;
    setSpecialAbilityIntro('判定履歴を確認しています。');
    setStatus('判定履歴を確認中');
    try {
        const data = await fetchSpecialAbilityJson('/api/special-ability/status', { customerRef });
        if (requestToken !== state.specialAbility.requestToken || customerRef !== getSelectedCustomerRef()) return;
        if (data.state === 'completed' && data.ability) {
            renderSpecialAbilityResult(data.ability);
            return;
        }
        if (data.state === 'finalizing') {
            state.specialAbility.state = 'finalizing';
            setSpecialAbilityIntro('判定結果を保存しています。少し待ってから店内リストを更新してください。');
            setStatus('結果を保存中');
            return;
        }
        state.specialAbility.state = 'available';
        const ready = state.specialAbility.assetsReady;
        setSpecialAbilityIntro(
            ready ? '準備ができました。端末をお客様へ渡して判定を始めてください。' : '判定画像を準備しています。',
            { canStart: ready }
        );
        setStatus(ready ? '判定可能' : '画像を準備中');
    } catch (error) {
        if (requestToken !== state.specialAbility.requestToken) return;
        setSpecialAbilityIntro(error?.message || '判定履歴を確認できませんでした。');
        setStatus(error?.message || '判定履歴を確認できませんでした', 'error');
    } finally {
        if (requestToken === state.specialAbility.requestToken) {
            state.specialAbility.busy = false;
            if ($('specialAbilityStart') && state.specialAbility.state === 'available') {
                $('specialAbilityStart').disabled = !state.specialAbility.assetsReady;
            }
        }
    }
}

async function startSpecialAbilityAssessment() {
    const customerRef = getSelectedCustomerRef();
    if (!customerRef || state.specialAbility.busy || !state.specialAbility.assetsReady) return;
    state.specialAbility.busy = true;
    if ($('specialAbilityStart')) $('specialAbilityStart').disabled = true;
    setStatus('判定を開始しています');
    try {
        const data = await fetchSpecialAbilityJson('/api/special-ability/start', { customerRef });
        if (customerRef !== getSelectedCustomerRef() || state.mode !== 'ability') return;
        state.specialAbility.customerRef = customerRef;
        state.specialAbility.token = String(data.token || '');
        renderSpecialAbilityQuestion(data.question);
    } catch (error) {
        setSpecialAbilityIntro(error?.message || '判定を開始できませんでした。', {
            canStart: error?.code !== 'already_completed' && state.specialAbility.assetsReady
        });
        setStatus(error?.message || '判定を開始できませんでした', 'error');
        if (error?.code === 'already_completed') await checkSpecialAbilityStatus();
    } finally {
        state.specialAbility.busy = false;
        if ($('specialAbilityStart') && state.specialAbility.state === 'available') {
            $('specialAbilityStart').disabled = !state.specialAbility.assetsReady;
        }
    }
}

async function submitSpecialAbilityAnswer(optionId) {
    const abilityState = state.specialAbility;
    if (abilityState.busy || abilityState.state !== 'in_progress' || !abilityState.token || !abilityState.question) return;
    const elapsedMs = Math.max(0, performance.now() - abilityState.questionShownAt);
    abilityState.busy = true;
    setSpecialAbilityOptionsDisabled(true);
    setStatus('回答を記録しています');
    try {
        const data = await fetchSpecialAbilityJson('/api/special-ability/answer', {
            token: abilityState.token,
            questionId: abilityState.question.id,
            optionId: String(optionId || ''),
            elapsedMs
        });
        if (data.state === 'completed' && data.ability) {
            renderSpecialAbilityResult(data.ability);
            return;
        }
        abilityState.token = String(data.token || '');
        renderSpecialAbilityQuestion(data.question);
    } catch (error) {
        if (['expired_token', 'customer_left_store', 'invalid_round_order'].includes(error?.code)) {
            resetSpecialAbilitySession();
            setSpecialAbilityIntro(error?.message || '判定を最初からやり直してください。', {
                canStart: error?.code !== 'customer_left_store' && state.specialAbility.assetsReady
            });
        } else if (error?.code === 'finalizing') {
            abilityState.state = 'finalizing';
            setSpecialAbilityIntro(error.message || '判定結果を保存しています。');
        } else {
            setSpecialAbilityOptionsDisabled(false);
        }
        setStatus(error?.message || '回答を記録できませんでした', 'error');
    } finally {
        abilityState.busy = false;
    }
}

function setReadingMode(mode) {
    const nextMode = mode === 'ability' && state.specialAbility.enabled ? 'ability' : 'tarot';
    state.mode = nextMode;
    const isAbility = nextMode === 'ability';
    if ($('tarotReadingBoard')) $('tarotReadingBoard').hidden = isAbility;
    if ($('specialAbilityBoard')) $('specialAbilityBoard').hidden = !isAbility;
    if ($('tarotCustomerSectionTitle')) $('tarotCustomerSectionTitle').textContent = isAbility ? '判定するお客様' : '送信先';
    if ($('tarotReadingKicker')) $('tarotReadingKicker').textContent = isAbility ? 'TROY ABILITY JUDGMENT' : 'TROY STAFF TAROT';
    if ($('tarotReadingTitle')) $('tarotReadingTitle').textContent = isAbility ? '異能航路' : 'タロット航路';
    document.querySelectorAll('[data-reading-mode]').forEach((button) => {
        const active = button.dataset.readingMode === nextMode;
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-selected', active ? 'true' : 'false');
    });
    if (state.storeData) renderStoreCustomers(state.storeData, getSelectedCustomerRef());
    if (isAbility) {
        checkSpecialAbilityStatus();
    } else {
        setStatus('待機中');
        updateSendButtonState();
    }
}

async function loadSpecialAbilityConfig() {
    try {
        const data = await fetchSpecialAbilityJson('/api/special-ability/config');
        if (!data.enabled) return;
        state.specialAbility.bootstrapToken = '';
        state.specialAbility.terminalSession = String(data.terminalSession || '').trim();
        if (!state.specialAbility.terminalSession) return;
        try {
            sessionStorage.setItem(SPECIAL_ABILITY_SESSION_KEY, state.specialAbility.terminalSession);
        } catch (_error) {
            // The in-memory session remains valid when storage is unavailable.
        }
        state.specialAbility.enabled = true;
        state.specialAbility.totalRounds = Math.max(1, Math.min(24, Math.trunc(Number(data.totalRounds) || 12)));
        state.specialAbility.assetVersion = Math.max(1, Math.trunc(Number(data.assetVersion) || 3));
        if ($('readingModeSwitch')) $('readingModeSwitch').hidden = false;
        document.querySelector('[data-reading-mode="tarot"]')?.classList.add('is-active');
        try {
            await preloadSpecialAbilityImages();
            state.specialAbility.assetsReady = true;
            if (state.mode === 'ability') checkSpecialAbilityStatus();
        } catch (error) {
            state.specialAbility.assetsReady = false;
            if (state.mode === 'ability') {
                setSpecialAbilityIntro('判定画像を読み込めませんでした。画面を再読み込みしてください。');
                setStatus(error?.message || '判定画像を読み込めませんでした', 'error');
            }
        }
    } catch (_error) {
        state.specialAbility.enabled = false;
    }
}

function formatCustomerJoinedAt(joinedAtMs) {
    const value = Number(joinedAtMs || 0);
    if (!value) return '';
    try {
        return new Intl.DateTimeFormat('ja-JP', { hour: '2-digit', minute: '2-digit' }).format(new Date(value));
    } catch {
        return '';
    }
}

function setCustomerListStatus(message, tone = '') {
    const element = $('tarotCustomerListStatus');
    if (!element) return;
    element.textContent = message;
    element.classList.toggle('is-error', tone === 'error');
}

function renderStoreCustomers(data, previousValue = '') {
    const select = $('tarotCustomerRef');
    if (!select) return;
    state.storeData = data || null;
    const customers = Array.isArray(data?.customers) ? data.customers : [];
    const linkedCustomers = customers.filter((customer) => customer?.lineLinked && customer?.customerRef);
    const selectableCustomers = state.mode === 'ability'
        ? customers.filter((customer) => customer?.customerRef)
        : linkedCustomers;
    select.replaceChildren();

    const placeholder = document.createElement('option');
    placeholder.value = '';
    placeholder.textContent = data?.isOpen
        ? (customers.length ? 'お客様を選択' : '入店中のお客様はいません')
        : 'TROYはCLOSE中です';
    select.appendChild(placeholder);

    customers.forEach((customer, index) => {
        const option = document.createElement('option');
        const joinedAt = formatCustomerJoinedAt(customer.joinedAtMs);
        const selectable = state.mode === 'ability' || customer.lineLinked;
        option.value = selectable ? String(customer.customerRef || '') : `unlinked-${index + 1}`;
        option.disabled = !selectable;
        option.textContent = [
            String(customer.displayName || 'お客様'),
            joinedAt ? `${joinedAt}入店` : '',
            state.mode === 'tarot' && !customer.lineLinked ? 'LINE未連携' : ''
        ].filter(Boolean).join(' / ');
        select.appendChild(option);
    });

    if (selectableCustomers.some((customer) => customer.customerRef === previousValue)) {
        select.value = previousValue;
    }
    select.disabled = selectableCustomers.length === 0;
    const unlinkedCount = customers.length - linkedCustomers.length;
    if (!data?.isOpen) {
        setCustomerListStatus('営業開始後、入店したお客様が表示されます。');
    } else if (!customers.length) {
        setCustomerListStatus('現在、入店中のお客様はいません。');
    } else if (state.mode === 'ability') {
        setCustomerListStatus(`判定可能 ${customers.length}名`);
    } else {
        const unlinkedText = unlinkedCount ? ` / LINE未連携 ${unlinkedCount}名` : '';
        setCustomerListStatus(`LINE送信可 ${linkedCustomers.length}名 / 店内 ${customers.length}名${unlinkedText}`);
    }
    updateSendButtonState();
}

async function loadStoreCustomers() {
    if (state.customersLoading) return;
    const select = $('tarotCustomerRef');
    const refreshButton = $('tarotRefreshCustomers');
    const previousValue = String(select?.value || '').trim();
    state.customersLoading = true;
    if (select) select.disabled = true;
    if (refreshButton) refreshButton.disabled = true;
    setCustomerListStatus('店内リストを読み込んでいます。');
    updateSendButtonState();

    try {
        const response = await fetch('/api/tarot-reading/customers', {
            method: 'GET',
            headers: { Accept: 'application/json' },
            cache: 'no-store'
        });
        const text = await response.text();
        let data = null;
        try {
            data = text ? JSON.parse(text) : null;
        } catch {
            data = null;
        }
        if (!response.ok || !data?.success) {
            throw new Error(data?.error || '店内リストを読み込めませんでした');
        }
        renderStoreCustomers(data, previousValue);
    } catch (error) {
        if (select) {
            select.replaceChildren();
            const option = document.createElement('option');
            option.value = '';
            option.textContent = '店内リストを読み込めませんでした';
            select.appendChild(option);
            select.disabled = true;
        }
        setCustomerListStatus(error?.message || '店内リストを読み込めませんでした。', 'error');
    } finally {
        state.customersLoading = false;
        if (refreshButton) refreshButton.disabled = false;
        updateSendButtonState();
        if (state.mode === 'ability' && getSelectedCustomerRef()) checkSpecialAbilityStatus();
    }
}

async function sendReading() {
    const button = $('tarotSendLine');
    const payload = buildPayload();
    if (!payload.customerRef) {
        setStatus('送信先を入力してください。', 'error');
        return;
    }
    const requiredCardCount = SPREAD_MODES[payload.spreadMode]?.count || 1;
    if (payload.cards.length !== requiredCardCount) {
        setStatus(payload.spreadMode === 'triple' ? 'カードを3枚選択してください。' : 'カードを選択してください。', 'error');
        return;
    }
    if (!payload.resultText) {
        setStatus('送信本文が空です。', 'error');
        return;
    }

    const previousText = button?.textContent || '';
    if (button) {
        button.dataset.sending = 'true';
        button.disabled = true;
        button.textContent = '送信中';
    }
    setStatus('LINEへ送信しています。');

    try {
        const response = await fetch('/api/tarot-reading/send', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const text = await response.text();
        let data = null;
        try {
            data = text ? JSON.parse(text) : null;
        } catch {
            data = null;
        }
        if (!response.ok || !data?.success) {
            const detail = data?.details ? `: ${data.details}` : '';
            throw new Error(`${data?.error || '送信に失敗しました'}${detail}`);
        }
        setStatus(`送信済み ${data.lineUserIdMasked || ''}`.trim(), 'success');
    } catch (error) {
        setStatus(error?.message || '送信に失敗しました。', 'error');
    } finally {
        if (button) {
            delete button.dataset.sending;
            button.textContent = previousText;
            updateSendButtonState();
        }
    }
}

function bindEvents() {
    $('tarotCardSearch')?.addEventListener('input', renderCardGrid);
    $('tarotCustomerRef')?.addEventListener('change', () => {
        updateSendButtonState();
        if (state.mode === 'ability') checkSpecialAbilityStatus();
    });
    $('tarotRefreshCustomers')?.addEventListener('click', loadStoreCustomers);
    $('tarotSendLine')?.addEventListener('click', sendReading);
    $('specialAbilityStart')?.addEventListener('click', startSpecialAbilityAssessment);
    document.querySelectorAll('[data-reading-mode]').forEach((button) => {
        button.addEventListener('click', () => setReadingMode(button.dataset.readingMode));
    });
}

function init() {
    renderTopics();
    renderSubtopics();
    renderDeckTabs();
    renderSpreadMode();
    renderSpreadSlots();
    renderOrientation();
    renderCardGrid();
    updateResult();
    bindEvents();
    setReadingMode('tarot');
    loadStoreCustomers();
    loadSpecialAbilityConfig();
}

window.TarotReadingApp = {
    getState: () => ({ ...state, tripleSelections: state.tripleSelections.map((selection) => selection ? { ...selection } : null) }),
    buildReading,
    buildStaffReading,
    buildLineReading,
    buildThreeCardStaffReading,
    buildThreeCardLineReading,
    buildThreeCardReadingBundle,
    getSpecialReadingBody,
    getWeatherStatus,
    getReadingWeatherStatus,
    getThreeCardWeatherStatus,
    getThreeCardFlow,
    getThreeCardPattern,
    getThreeCardVerdict,
    getSubtopicVerdict,
    getSubtopicForecast,
    getSubtopicLineBody,
    getSubtopic,
    getSubtopicReadingFrame,
    getThreeCardSpreadFrame,
    verdicts: SUBTOPIC_VERDICTS,
    spreadModes: SPREAD_MODES,
    threeCardSpreadFrames: THREE_CARD_SPREAD_FRAMES,
    topics: TOPICS,
    subtopics: SUBTOPICS,
    allCards
};

init();
